class Post(BaseModel):
    # 推文 ID
    id: str
    # 正文
    text: str
    # 推文链接
    url: str
    # 发布时间 上游提供的发布时间；缺失时为空。
    created_at: str = ""
    # 作者 ID
    author_id: str = ""
    # 作者账号
    author_username: str = ""
    # 回复目标 ID
    reply_to_id: str = ""
    # 点赞数
    like_count: int = 0
    # 转帖数
    repost_count: int = 0
    # 回复数
    reply_count: int = 0


class User(BaseModel):
    # 用户 ID
    id: str
    # 用户账号
    username: str
    # 显示名称
    name: str = ""
    # 简介
    description: str = ""
    # 关注者数
    followers_count: int = 0
    # 关注数
    following_count: int = 0
    # 主页链接
    url: str


class Credential(BaseModel):
    """Credential fields (the platform injects them with every call; a plugin never stores them).

    Every field may be absent: `required` means "the UI insists on it", not "every call carries it"."""

    # 登录令牌
    auth_token: str = ""
    # CSRF 令牌
    ct0: str = ""
    # 代理地址
    proxy: str = ""


def credential(ctx: Any) -> Credential:
    """Read this call's credential into a typed object (works for both operation and source ctx)."""
    return ctx.credential_as(Credential)


class DeletePostIn(BaseModel):
    """Inputs of "删除推文".

    删除当前账号有权删除的推文；操作不可撤销，失败不会自动重试。"""

    # 推文 ID
    id: str


class DeletePostOut(BaseModel):
    """Outputs of "删除推文".

    删除当前账号有权删除的推文；操作不可撤销，失败不会自动重试。"""

    # 已删除
    deleted: bool
    # 推文 ID
    id: str


DeletePostHandler = Callable[[Ctx, DeletePostIn], Union[DeletePostOut, Awaitable[Optional[DeletePostOut]], None]]


def on_delete_post(p: Plugin, fn: DeletePostHandler) -> None:
    """Register the implementation of "删除推文". The handler may be an async def or a plain function."""

    async def _invoke(ctx: Ctx, raw: Dict[str, Any], out: Emitter) -> None:
        res = fn(ctx, DeletePostIn.model_validate(raw))
        if inspect.isawaitable(res):
            res = await res
        if res is not None:
            out.vars(res)

    p.register("delete_post", _invoke)


